edits.repl:
for block in self.cfg.get_blocks_in_order():
    if block in cleanup_visited:
        continue
    if block.start_offset in body_offsets:
        continue
    if block.start_offset < body_end:
        continue
    # [R74-fix2 - F-PAD] 正常退出清理的入口必须由 with 自身驱动。若该块
    # 是 WithRegion 之外某个条件跳转（POP_JUMP_*，argval 指向本块）的直接
    # 目标，则它是外层 if/elif 的分支块（例如
    # `if os.path.exists(path): ... else: return None`）。误收会把该
    # return 让渡给 with，外层 if 因此失去 else，重编译后条件跳转改指向
    # 相邻的 return-None 块，产生 control-flow first-diff。
    _ext_cond_target = False
    for _p in block.predecessors:
        if _p in cleanup_visited:
            continue
        _pl = _p.get_last_instruction()
        if (_pl is not None and _pl.opname.startswith('POP_JUMP_')
                and _pl.argval == block.start_offset):
            _ext_cond_target = True
            break
    if _ext_cond_target:
        continue
